corporate_design.toad_component_blueprint:
canvas {
  size: 960px 580px;
  fill: #0A1128;
  font-family: "Inter, sans-serif";
}

>trustNavy = #0A1128;
>electricBlue = #0066FF;
>checkoutGreen = #00D084;
>cardSurface = #121C38;
>white = #FFFFFF;

rect #kpiBanner {
  at: center of canvas;
  size: 880px 480px;
  fill: >cardSurface;
  radius: 16px;
}

text #brandHeader {
  at: top left of #kpiBanner offset 36px 32px;
  content: "PAYPULSE // GLOBAL SETTLEMENT";
  font-size: 14px;
  font-weight: 700;
  color: >electricBlue;
}

text #amountHero {
  at: below #brandHeader offset 16px;
  content: "€ 2,849,200.50";
  font-size: 48px;
  font-weight: 800;
  color: >white;
}

rect #successBadge {
  at: below #amountHero offset 20px;
  size: 180px 32px;
  fill: alpha(>checkoutGreen, 0.15);
  radius: 8px;
}

text #successText {
  at: center of #successBadge;
  content: "✔ INSTANT PAYOUT OK";
  font-size: 11px;
  font-weight: 700;
  color: >checkoutGreen;
}
